#!/usr/bin/env python3
"""Deterministic, source-bound integration of the completed EOS campaign.

Always starts from the saved pre-revision manuscript. Does not alter results.
"""
from pathlib import Path
import difflib
import hashlib
import json
import re

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
SOURCE = HERE / 'before/article1/template.tex'
TARGET = ROOT / 'article1/template.tex'
original = SOURCE.read_text()
text = original
changes = []

def paragraph(prefix, replacement):
    global text
    matches = [line for line in text.splitlines() if line.startswith(prefix)]
    assert len(matches) == 1, (prefix, len(matches))
    old = matches[0]
    assert text.count(old) == 1
    text = text.replace(old, replacement)
    changes.append({'kind': 'paragraph', 'anchor': prefix, 'before': old, 'after': replacement})

def exact(old, new):
    global text
    assert text.count(old) == 1, (old, text.count(old))
    text = text.replace(old, new)
    changes.append({'kind': 'exact', 'before': old, 'after': new})

paragraph(r'\abstract{', r'''\abstract{Streaming large language model (LLM) services can expose response-length metadata even when payloads are encrypted. We evaluate a fixed T5 reconstructor through 6600 reconstructions from validated application-layer length traces, selecting candidates by sampling-processed transition scores through the first end-of-sequence (EOS) token. For 300 aligned prompts per model, five archived-reference cohorts yield mean term-frequency cosine scores ($\phi$) of 0.509--0.577; two additional archived cohorts have malformed word boundaries. Separately collected TinyLlama and Phi-3.5-mini responses with verified detokenization yield means of 0.468 and 0.527. Legacy rendering of their saved token IDs reproduces all 600 corresponding archived references and length vectors. Changing both the trace and scoring reference increases mean $\phi$ by 0.384 and 0.397 under matched reconstruction settings. In two-model pilots, four of six partial-ablation contrasts remain significant after Holm correction; neither cross-prompt contrast is conclusive. Five framing transformations reduce frozen-reconstructor mean scores by 43.8--89.6\%. A five-seed study with a local empirical maximum-a-posteriori (MAP) length inverse recovers much of the loss under bucketing and batching. Reconstruction scopes and retained encoder coverage differ across these experiments. The findings quantify lexical behavior of an instrumented pipeline and demonstrate the importance of validating both observations and reference rendering. They do not measure semantic disclosure or demonstrate passive extraction from encrypted transport.}''')
exact(r'The historical line-collector discrepancy motivates the validation in Section~\ref{sec:measurement-audit}; all quantitative reconstruction results reported below use recorded, validated input vectors.', r'Validation in Section~\ref{sec:measurement-audit} binds each input vector to its source log and scoring reference. All quantitative reconstruction results reported below come from the completed campaign with EOS-bounded candidate selection.')
exact('A separate two-model experiment uses newly generated responses with verified full-sequence detokenization.', 'A separate two-model experiment uses previously collected responses with verified full-sequence detokenization, reconstructed in the same completed campaign.')
paragraph('The contribution is an evaluation', r'''The contribution is an evaluation with explicit input provenance: 2100 reconstructions from validated archived lengths, 600 reconstructions of separately collected responses with verified decoding, two-model pilots of partial trace ablations and five framing configurations, and a five-seed MAP-inverse evaluation. All 6600 reconstructions were executed in the completed campaign; no earlier reconstruction predictions enter the reported results. The pilots and MAP study use different reconstruction scopes, so their baselines are not interchangeable. Full input vectors, decoder inputs, random seeds, candidate sequences, transition scores, generated texts and independent metric checks are retained in the accompanying artifact package. The source project is hosted at \url{https://github.com/jackaugustyn/LLeakM}. Appendix~\ref{app:runs} identifies the completed experiment artifacts and the frozen victim-response inputs.''')
exact('the newly generated two-model cohort', 'the verified-reference two-model cohort')
paragraph('The archived collector used', r'''Every reconstruction input is an explicit vector of UTF-8 payload lengths obtained from the retained generation log. Validation recomputes each fragment's byte length, checks its ordered position and verifies that the concatenated fragments equal the scoring reference. Source hashes and immutable sample inventories bind the vectors, references and recorded seeds to the completed campaign. The experiments do not infer lengths from line parsing or undocumented historical reconstruction inputs.''')
paragraph('The primary results below instead', r'''The primary cohort reconstructs all 2100 validated archived vectors with the EOS-bounded selector defined below. The two verified-reference cohorts and all control, defense and MAP conditions use the same pinned reconstruction implementation. The reconstructor is seeded after checkpoint loading so that cache initialization does not change a sample's random stream. The current campaign reuses frozen victim responses and length vectors; it does not regenerate victim responses.''')
paragraph('To evaluate the affected models', r'''To evaluate the affected models with ordinary reference text, a separate collection produced 300 responses per model from the same prompts using contextual detokenization. All 600 stored responses pass exact agreement between concatenated fragments and full-sequence decoding, with token IDs, tokenizer and checkpoint provenance retained; all contain ASCII spaces. They are reconstructed anew in the present campaign and reported as separate cohorts. Their collection checkpoint revisions, precision and placement are pinned; identity with the historical execution is not established.''')
paragraph('The inversion pipeline follows', r'''The inversion pipeline follows the sequence-to-text procedure introduced by Weiss \emph{et al.}~\cite{weiss2024prompt}. It first splits a length vector at observations equal to one and merges short chunks using a ten-unit minimum, with an additional list-boundary heuristic. These are heuristic segments rather than verified sentences. The first segment is decoded using \texttt{royweiss1/T5\_FirstSentences}; later segments use \texttt{royweiss1/T5\_MiddleSentences}, conditioned on the immediately preceding selected segment. T5 generation uses stochastic sampling with top-$k=50$, temperature 1 and a two-token no-repeat n-gram constraint. For candidate $c$, let $\ell_{c,t}$ be its normalized transition log-score after those sampling constraints, and let $\tau_c$ be the first generated EOS position, or the final returned position if EOS is absent. The selector uses
\begin{equation}
S(c)=\sum_{t=1}^{\tau_c}\ell_{c,t}.
\end{equation}
The EOS transition is included and all subsequent PAD positions are excluded. The score is not length-normalized. Among duplicate decoded texts, the highest score is retained; equal-score ties preserve candidate order. The selected text supplies the next segment's context.''')
paragraph('These scores are obtained after', r'''These scores use the sampling-processed distributions, not the unconstrained model logits. Nonfinite scores before or at EOS cause validation failure; padding after EOS does not contribute to selection. Every generated candidate is retained for independent verification; calls with three candidates also retain their transition scores. All three-candidate conditions use this rule throughout the complete response, including subsequent context updates. The one-candidate MAP experiment bypasses candidate ranking. Appendix~\ref{app:selector} reports full-campaign validation.''')
exact(r'{PAD-inclusive score sum\\select one text per segment}', r'{Score sum through first EOS\\select one text per segment}')
paragraph(r'\caption{Executed reconstruction pipeline.', r'''\caption{Executed reconstruction pipeline. Unmodified conditions pass lengths directly to segmentation. Candidate scores include the first EOS and exclude all subsequent padding before each context update (Section~\ref{sec:reconstructor}); the first segment has no reconstructed context. Main and verified-reference runs request all segments with three samples per segment; 96-token pilots allow up to three segments with three samples each; the five-seed MAP study uses one sample for the first segment per seed. The 80-token encoder limit includes the instruction and context. All settings score their output against the full stored response.}''')
paragraph('The completed experiments comprise 2100', r'''The completed EOS-selector campaign comprises 2100 reconstructions from validated archived length traces, 600 reconstructions of separately collected TinyLlama and Phi-3.5-mini responses, 240 trace-control reconstructions, 360 defense-pilot reconstructions and 3300 MAP reconstructions. Every planned sample is present and independently checked. The primary and verified-reference cohorts request all available heuristic segments; the 96-token pilots allow up to three, and the 512-token MAP experiment reconstructs one. These differences preclude interpreting cross-experiment score differences as victim-budget effects alone.''')
paragraph(r'Table~\ref{tab:trace_controls} shows', r'''Table~\ref{tab:trace_controls} shows lower scores after shuffling or constant replacement for both models. For Qwen, the true-trace mean is 0.3235 versus 0.1840 after shuffling and 0.1169 for a constant trace; both contrasts are significant after Holm correction ($p<0.0001$). For Llama, the true mean is 0.2917 versus 0.1870 after shuffling ($p=0.0002$) and 0.1252 for a constant trace ($p<0.0001$). Cross-prompt means are 0.2745 for Qwen and 0.2320 for Llama; neither adjusted signed-rank test is conclusive ($p=0.1169$ for each). The nominal mean-difference bootstrap intervals for those two contrasts exclude zero, but do not incorporate the Holm adjustment and concern a different estimand from the signed-rank test. Thus four of six contrasts support sensitivity to the altered features; the pilots do not establish a general advantage over unrelated prompt traces. Each control retains some response-dependent information, and transformations can also alter segmentation and encoder coverage.''')
paragraph(r'Table~\ref{tab:main_results} reports', r'''Table~\ref{tab:main_results} reports the completed reconstruction cohort, and Figure~\ref{fig:model_ci}a shows its mean scores with scenario-bootstrap intervals. For the five series without the observed malformed-word-boundary pattern, mean $\phi$ ranges from 0.5092 to 0.5768 and $\mathrm{LR}@0.5$ from 55.00\% to 76.67\%. Their ROUGE-1 precision is 0.2283--0.3284. These metrics quantify lexical overlap with the archived emitted text; they do not establish semantic fidelity or independently validate its historical full-sequence detokenization. Phi-1.5 remains a base-model stress test.''')
paragraph('The archived TinyLlama and Phi-3.5-mini references yield', r'''The archived TinyLlama and Phi-3.5-mini references yield means of 0.0832 and 0.1297, with no $\phi>0.5$ cases. These are reference-format diagnostics. The input vectors are verified byte-for-byte for all models, but reference defects remain part of these two scores. Across the 2100 reconstructions, all 62,757 available heuristic segments were attempted and 62,755 produced nonempty selected text; 1014 encoder calls exceeded the 80-token input limit. Two final segments, one each for Llama and Phi-1.5, produced empty text. No available segment was skipped by an earlier stop.''')
paragraph('Relative to the earlier stored reconstructions,', '')
exact('figures/latest_model_results.pdf', 'figures/eos_model_results.pdf')
exact('figures/latest_defense_tradeoff.pdf', 'figures/eos_defense_tradeoff.pdf')
exact(r'\caption{Completed all-segment reconstructions with scenario-bootstrap', r'\caption{Completed reconstructions with EOS-bounded selection and scenario-bootstrap')
paragraph(r'Table~\ref{tab:eos_completeness} compares', r'''Table~\ref{tab:eos_completeness} compares all 300 archived responses per model with the subset whose victim generation reached EOS. This completion criterion concerns the victim response and is separate from EOS handling in the T5 candidate selector. EOS restriction does not systematically increase $\phi$: Qwen2.5-3B rises from 0.5571 to 0.6043 ($n=50$), whereas Phi-1.5 falls from 0.5420 to 0.5108 ($n=144$). Phi-3.5-mini has no EOS-complete subset. EOS indicates completion of victim generation, not correct reconstruction; conditioning on it also changes the evaluated response subset.''')
paragraph(r'Table~\ref{tab:statistical_results} gives', r'''Table~\ref{tab:statistical_results} gives prompt-bootstrap intervals and Wilson intervals for the lexical threshold. Eighteen of 21 model pairs are significant after Holm correction, with the same decisions when the 60 scenario means are used as the paired units. The three inconclusive pairs are Qwen2.5-3B versus Llama-3.2-3B, Qwen2.5-3B versus Phi-1.5, and Llama-3.2-3B versus Phi-1.5. Qwen2.5-1.5B has a higher mean than each of the other four non-diagnostic series with significant adjusted tests. These are conditional comparisons on the stored references. The significant family also contains comparisons with malformed-reference diagnostics, which cannot be interpreted as transfer differences on ordinary model responses.''')
paragraph('For example, Qwen2.5-1.5B minus', r'''For example, Qwen2.5-1.5B minus Qwen2.5-3B has a mean difference of 0.0197 (prompt-bootstrap 95\% CI $[0.0055,0.0332]$, rank-biserial $r=0.1962$, $p_{\mathrm{Holm}}=0.0129$). The mean-difference interval and the adjusted signed-rank test both support a difference in this comparison, while retaining their distinct estimands and multiplicity treatment.''')
paragraph('The exploratory scenario analysis retains', r'''The exploratory scenario analysis retains the same 18 significant pairs (Table~\ref{tab:scenario_sensitivity}). All seven scenario-bootstrap intervals are wider than their prompt-bootstrap counterparts, by up to 44.8\% for Qwen2.5-3B. For the Qwen2.5-1.5B versus Qwen2.5-3B comparison, the mean difference remains 0.0197, with scenario-level $r=0.4011$ and $p_{\mathrm{Holm}}=0.0279$. Grouping the five variants changes the inference unit; agreement of significance decisions does not establish independence or generalization to unseen scenarios.''')
paragraph('New TinyLlama and Phi-3.5-mini generations passed', r'''The separately collected TinyLlama and Phi-3.5-mini responses pass full-sequence detokenization checks for all 300 prompts per model. Their current reconstruction means are 0.4677 and 0.5269 (Table~\ref{tab:fresh_results} and Figure~\ref{fig:model_ci}b), with $\mathrm{LR}@0.5$ of 44.33\% and 62.33\%. TinyLlama reached EOS in 177/300 responses; all Phi-3.5-mini responses reached the 512-token limit. All 8835 and 10,748 available reconstruction segments produced nonempty selected text, with 24 and 35 encoder calls truncated, respectively.''')
paragraph('Because legacy decoding of the newly saved IDs', r'''Because legacy decoding of the saved IDs exactly reproduces the archived references and vectors, the two renderings support a matched computational comparison with identical T5 settings and per-sample seeds. Both arms are reconstructed in the present EOS-selector campaign. Changing both the length trace and reference to full-sequence rendering increases mean $\phi$ by 0.3845 for TinyLlama (paired scenario-bootstrap 95\% CI $[0.3662,0.4029]$) and 0.3972 for Phi-3.5-mini ($[0.3806,0.4134]$). These intervals use 10,000 resamples of the 60 paired scenario means with seed \texttt{20261101}. The effect combines changed attacker input and changed scoring text; neither component is isolated. The two cohorts remain separate from the other five archived-reference series, whose original token IDs are unavailable.''')
paragraph('All five framing transformations reduce', r'''All five framing transformations reduce mean $\phi$ relative to their defense-pilot baseline (Table~\ref{tab:defense_results}), and all ten paired comparisons are significant after Holm correction. Reductions range from 43.8\% for \texttt{pad\_32} on Qwen to 89.6\% for \texttt{bucket\_8} on Qwen. Batching reduces scores by 70.9--79.3\% and changes the number of observable units from 96 to 48 or 24. Figure~\ref{fig:defense_tradeoff} relates these changes to payload overhead calculated from the actual saved transformation vectors.''')
paragraph('All 3300 MAP predictions exactly match', r'''All 3300 MAP reconstructions are present in the current campaign, and independent checks reproduce their per-record metrics and crossed-bootstrap intervals. A defense-aware inverse recovers much of the lexical score lost under bucketing and batching, but inversion also changes the sequence subsequently segmented and truncated by T5. With 80-token limits on both input and output, equal victim-token budgets do not imply equal encoder coverage or comparable sentence boundaries. The adaptive procedure uses the frozen, prompt-disjoint empirical length inverse followed by the unchanged T5 decoder, without end-to-end retraining on defended traces. Its scores therefore characterize this pipeline under limited adaptation; they do not isolate a defense's information loss or establish the performance of a fully retrained attacker.''')
paragraph('The strongest control evidence concerns', r'''Shuffling and constant replacement reduce lexical scores for both models after Holm correction. Neither cross-prompt contrast is conclusive under the adjusted signed-rank test. Thus the experiments support sensitivity to selected trace features, not a universal advantage of the target trace over every partial ablation. Controls preserve response-dependent quantities such as length, mean or histogram and can change segmentation. Their residual scores cannot be assigned entirely to the decoder's language prior. Estimating information-theoretic leakage would require a defined response variable, repeated sampling and a suitable estimator.''')
exact('Exact logged byte lengths remove the line-collector ambiguity from the reported reconstruction inputs.', 'Exact logged byte lengths and saved input vectors establish the observations used by the reconstructor.')
paragraph('For the largest mean in the archived-reference cohort,', r'''For the largest mean in the archived-reference cohort, $\mathrm{LR}@0.5$ is 76.00\% and ROUGE-1 precision is 0.3284. Neither quantity is a disclosure rate: lexical overlap does not verify an entity, proposition or actionable answer. No semantic annotation or task-specific disclosure evaluation was performed. Practical harm might involve recovered phrases, entities, refusals or topic cues, but the present metrics do not quantify those outcomes. Deployment-facing conclusions additionally require extraction of observables from encrypted traffic and validation under transport buffering and multiplexing.''')
paragraph('The three-candidate experiments retain a selector', r'''Candidate selection is verified through the first EOS, but its unnormalized sum of sampling-processed log-scores is still an implementation choice. Its preference across different candidate lengths is not a calibrated measure of correctness. The study evaluates one pair of pretrained T5 checkpoints with heuristic segmentation and fixed sampling settings; it does not compare ranking objectives or establish optimal reconstruction performance. The one-candidate MAP study has a different decoding scope and bypasses this selection rule.''')
exact('Reconstruction processes all heuristic segments in the primary and new-reference cohorts, up to three in the 96-token pilots, and one in MAP.', 'Reconstruction attempts every heuristic segment in the primary and verified-reference cohorts, with two empty terminal outputs in the archived cohort; the 96-token pilots allow up to three segments and MAP uses one.')
paragraph('The completed experiments comprise 6600 T5', r'''The completed campaign provides 6600 T5 reconstructions with EOS-bounded candidate selection and independent verification of the recorded candidates and metrics. Reconstruction from validated logged lengths yields mean lexical scores of 0.509--0.577 for five archived-reference cohorts. For separately collected TinyLlama and Phi-3.5-mini responses with verified full-sequence decoding, the means are 0.468 and 0.527. Legacy rendering of their saved token IDs exactly reproduces the corresponding archived references and length vectors. With both renderings reconstructed under matched T5 settings and seeds in this campaign, changing the input trace and scoring reference increases mean $\phi$ by 0.3845 and 0.3972. This computational comparison identifies observation and reference construction as consequential parts of the evaluation; it does not separate their individual contributions or establish an intrinsic model-vulnerability ranking.''')
paragraph('The partial-ablation controls support', r'''The partial-ablation controls support sensitivity to selected trace features: four of six contrasts remain significant after Holm correction, comprising shuffling and constant replacement for both models; neither cross-prompt contrast is conclusive. In the 96-token pilots, all ten model--transformation contrasts show significant score reductions after correction, ranging from 43.8\% to 89.6\%. These reductions describe the tested frozen reconstructor and realized transformations. The first-segment, five-seed study shows that an exact-prompt-disjoint MAP length inverse can recover much of the loss under bucketing and batching, although calibration shares scenario templates with the test set.''')
paragraph('These conclusions are conditional on the recorded implementation:', r'''Constant \texttt{pad\_32} encoder inputs show why positive lexical overlap need not demonstrate use of response-specific trace variation. Practical privacy claims require evidence beyond these lexical scores. Transform-dependent segmentation and the 80-token encoder limit change the retained input coverage, and payload-size accounting excludes transport costs and latency. Evaluations with matched observation coverage, unseen scenarios, extraction from encrypted traffic, and disclosure-oriented outcomes are needed to establish the deployment significance of these results.''')
paragraph('Supplementary Data S1 is the frozen local package', r'''The frozen local supplementary package \texttt{LLeakM-S2-EOS-20261102-v1} is supplied as a compressed archive with a SHA-256 manifest, a README and a CPU-only verification entry point. It contains the completed EOS-selector records, candidate evidence, analysis code, necessary source logs, model revision identifiers and manuscript files; model weights are obtained separately from the pinned checkpoints. The archive is prepared for accompanying submission and can be requested from the corresponding authors; public archival of this version remains pending. The source project repository is \url{https://github.com/jackaugustyn/LLeakM}. Table~\ref{tab:run_ids} identifies the original 512-token victim-response directories. All reported reconstruction results reside under \path{experiment_validation/selector_eos_20261101/}: \path{inference/cuda_full/} contains the 2100 archived-reference reconstructions, \path{secondary/cuda_full/} the 3900 control, defense and MAP records, and \path{inference/fresh_tinyllama_cuda/} and \path{inference/fresh_phi_cuda/} the two 300-response verified-reference reconstructions.''')
paragraph('Each completed run binds its sample inventory,', r'''Each completed run binds its sample inventory, source hashes, model files, code, seeds and environment to a protocol. Independent checks verify complete unique keys, saved text metrics, encoder input tokenization, segment coverage and cohort counts. All planned reconstructions are present; partial probes are excluded. The \path{inference_validation/} and \path{validation/} directories contain independent metric, candidate and statistical audits. In particular, \path{validation/main_fresh_factledger.json} and \path{validation/secondary_audit.json} supply the manuscript's numerical results. The \path{article_revision_20261102/} directory records the integrated table checks, plotting inputs, figure generator, manuscript build and supplementary verifier.''')
paragraph(r'The \path{review_revision_20261101/} directory', r'''The supplementary manifest binds the files actually distributed. Its verification entry point checks hashes, inventory completeness, per-record lexical cosine, candidate score boundaries and selection without loading model weights. Optional checks use the included pinned T5 tokenizers to verify encoder and output tokenization offline. The frozen victim-response inputs, including the 600 verified token-ID sequences, originate from \path{experiment_validation/revalidation_20261031/collection/} and \path{fresh_references/} and the original generation logs identified by their hashes. These files are source observations; earlier reconstruction predictions are not used in the manuscript.''')
paragraph(r'The earlier \path{analysis/repro_manifest.json}', r'''The campaign's \path{completed_manifest.json} records the experiment artifacts before manuscript integration; the supplementary manifest separately binds the integrated article and distributed data. These provenance records do not retroactively establish historical victim revisions or undocumented historical token IDs. Version-pinned reconstructor model cards and their retrieved text document the checkpoint provenance.''')
start = text.index(r'\section{Bounded Candidate-Selection Audit}')
end = text.index(r'\authorcontributions{', start)
replacement = r'''\section{Full-Campaign Candidate and Metric Validation}\label{app:selector}
The completed campaign retains 6600 reconstruction records, 86,788 decoder calls and 253,764 generated candidates. Of the decoder calls, 83,488 sample three candidates and 3300 produce the single candidate used in MAP. Every call records encoder inputs, generated token IDs, decoded text, the first-EOS boundary and selected text. The three-candidate calls additionally record transition scores; single-candidate MAP calls omit score computation and ranking. The audit recomputes sums through the first EOS, checks duplicate-text handling and tie order, and verifies the selected context used by subsequent segments.

Across the candidate records, 4,540,261 generated positions contribute to the selector scores. A total of 142,629 candidates have a returned tail after their first EOS, comprising 393,353 excluded positions. Each such tail includes a nonfinite processed score; no nonfinite score enters an EOS-bounded sum. Candidates without EOS retain all returned generation steps. These counts describe the complete retained candidate inventory. They do not measure semantic correctness or compare alternative ranking objectives.

Independent checks reproduce the reconstruction metrics, cohort summaries and statistical intervals from the current predictions. All requested archived and verified-reference segments were attempted; the archived cohort contains two empty terminal selections, which are retained in its scored outputs. The audit also verifies all 3900 secondary records and their source bindings. The accompanying supplementary verifier provides checks of these current outputs without GPU inference; full reproduction additionally requires the pinned model weights and recorded execution environment.

'''
changes.append({'kind': 'section', 'anchor': 'app:selector', 'before': text[start:end], 'after': replacement})
text = text[:start] + replacement + text[end:]
paragraph(r'\dataavailability{', r'''\dataavailability{The source project repository is \url{https://github.com/jackaugustyn/LLeakM}. The frozen local supplementary package \texttt{LLeakM-S2-EOS-20261102-v1} contains the completed EOS-selector reconstructions and candidate evidence, verified victim token IDs, necessary source logs, reference-validation records, analysis code and a file-level SHA-256 manifest with a verification entry point. It is prepared for accompanying submission and available from the corresponding authors on request; public archival of this completed version remains pending. Appendix~\ref{app:runs} identifies its version, contents and provenance boundaries.}''')

paragraph('The control and defense experiments use explicit', r"""The control and defense experiments use explicit BLAKE2s-derived, condition-specific decoder seeds and record every seed and transformed vector. Shuffling uses seed $20260706+17i$ for prompt index $i$. Cross-prompt inputs cycle the trace of donor index $(i\bmod30)+1$ to the target's trace length. Random padding has a separately recorded transformation seed, and its payload overhead is calculated from the actual saved padding realization. The current campaign reuses these frozen seeds and vectors. The control and defense baseline reconstructions use distinct decoder seeds, so even their identical undefended length traces can yield different mean scores.""")
exact('For newly collected streams the collector also checks', 'For the verified-reference streams the collector also checks')
exact('Holding the newly recorded token IDs fixed', 'Holding the separately recorded token IDs fixed')
exact('legacy decoding of newly recorded token IDs reproduces', 'legacy decoding of the saved token IDs reproduces')
exact('For fixed newly recorded token IDs', 'For fixed saved token IDs')
exact('Newly generated references are verified for TinyLlama and Phi-3.5-mini', 'Separately collected references are verified for TinyLlama and Phi-3.5-mini')
exact(r'\path{experiment_validation/revalidation_20261031/collection/} and \path{fresh_references/}', r'\path{experiment_validation/revalidation_20261031/}, specifically its \path{collection/} and \path{fresh_references/} subdirectories')

# Integrate complete source-generated blocks, preserving each table label.
tables = json.loads((HERE / 'tables.json').read_text())
for label, block in tables.items():
    pattern = re.compile(r'\\begin\{(table\*?)\}.*?\\end\{\1\}', re.S)
    matches = [m for m in pattern.finditer(text) if r'\label{' + label + '}' in m.group()]
    assert len(matches) == 1, label
    m = matches[0]
    text = text[:m.start()] + block.strip() + text[m.end():]
    changes.append({'kind': 'table', 'label': label})

# Unchanged literature and author declarations are protected.
for macro in ('Title', 'Author', 'AuthorNames', 'address', 'corres', 'authorcontributions', 'funding', 'institutionalreview', 'informedconsent', 'conflictsofinterest'):
    pattern = r'^\\' + macro + r'(?:\[[^\]]*\])?\{.*$'
    assert re.findall(pattern, original, re.M) == re.findall(pattern, text, re.M), macro
cites = lambda s: sorted({key.strip() for body in re.findall(r'\\cite\{([^}]+)\}', s) for key in body.split(',')})
assert cites(original) == cites(text)
assert 'PAD-inclusive' not in text
assert 'Bounded Candidate-Selection' not in text
assert len(tables) == 13
TARGET.write_text(text)
(HERE / 'article_changes.json').write_text(json.dumps({'source_sha256': hashlib.sha256(SOURCE.read_bytes()).hexdigest(), 'target_sha256': hashlib.sha256(TARGET.read_bytes()).hexdigest(), 'changes': changes}, indent=2) + '\n')
(HERE / 'article.diff').write_text(''.join(difflib.unified_diff(original.splitlines(True), text.splitlines(True), fromfile='before/article1/template.tex', tofile='article1/template.tex')))
print(json.dumps({'paragraph_and_exact_edits': len(changes)-13, 'tables': len(tables), 'target': str(TARGET)}))
